-- Add Arabic fields for bilingual project publishing without duplicating project records.
ALTER TABLE projects ADD COLUMN name_ar TEXT;
ALTER TABLE projects ADD COLUMN short_description_ar TEXT;
ALTER TABLE projects ADD COLUMN description_ar TEXT;
UPDATE projects SET name_ar='WAYNAH | وَيْنَه؟', short_description_ar='منصة للاستكشاف الجغرافي والمعلومات المحلية الموثوقة في اليمن، تربط المكان بسياقه الإداري وبياناته ودرجة التحقق منه.', description_ar='المعلومات المحلية والعناوين غير الرسمية متفرقة، وقد تختلف كتابة الأسماء ومواقع الأماكن ومصادر بياناتها، مما يصعّب الوصول إلى معلومة مكانية موثوقة.\n\nبناء بنية موحدة لاكتشاف الأماكن والخدمات في اليمن، مع هرمية جغرافية ومحرك بحث مكاني ونموذج ثقة وتحقق قابل للتدقيق.\n\nالأفراد والباحثون عن الأماكن، والأنشطة المحلية، ومقدمو الخدمات، والجهات التي تحتاج إلى بيانات مكانية منظمة.\n\nتحويل سؤال «وينه؟» إلى اكتشاف مكاني منظم يوضح المكان وسياقه وكيفية الوصول إليه ومدى موثوقية بياناته.\n\nMonorepo يضم تطبيقات الويب وواجهات API وخدمات المجال. توثيق المشروع يوضح تدفقاً من واجهات Next.js إلى بوابة Hono ثم خدمات المجال وطبقة Prisma وقاعدة PostgreSQL/PostGIS.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='waynah';
UPDATE projects SET name_ar='Yemen AI Platform', short_description_ar='منصة ذكاء اصطناعي ثنائية اللغة تجمع واجهات المحادثة والبحث في المستندات والاسترجاع المعزز بالتوليد وإدارة النماذج.', description_ar='تشتت المعرفة والمستندات وأدوات الذكاء الاصطناعي، وصعوبة ضبط الوصول ومراجعة مصادر الإجابات.\n\nتوفير منصة محلية/ذاتية التشغيل لربط المستندات بالاسترجاع والبحث وإدارة النماذج والمستخدمين.\n\nالفرق التي تحتاج إلى مساعد معرفي ثنائي اللغة وبحث منظم في المستندات.\n\nجمع المساعد المعرفي وإدارة المستندات والنماذج والصلاحيات ضمن منصة واحدة.\n\nتطبيق Python/FastAPI مع وحدات API وخدمات أساسية وطبقات للمعرفة والمستندات وإدارة النماذج. توثيق المستودع يتناول RAG والاستدلال المحلي ومراجعات الاستقرار والأمان.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='yemen-ai';
UPDATE projects SET name_ar='M.GH.AL Content Studio', short_description_ar='نظام تشغيل للمحتوى العربي يجمع التخطيط والتوليد بالذكاء الاصطناعي وتصميم الصور وإدارة المسودات والنشر عبر واجهات رسمية.', description_ar='تجزؤ دورة إنتاج المحتوى بين أدوات الكتابة والتصميم ولوحات النشر، مع تكرار إعداد النسخ المناسبة لكل منصة.\n\nتوحيد دورة المحتوى من الفكرة إلى المراجعة والتصميم والجدولة والنشر مع سجل تدقيق وتكاملات رسمية.\n\nصنّاع المحتوى وأصحاب العلامات والحسابات الاجتماعية الذين يديرون محتوى عربياً متعدد المنصات.\n\nتوليد نسخ متعددة من فكرة واحدة، وإنشاء صور عربية RTL، وإدارة الموافقات والتكاملات من مساحة عمل واحدة.\n\nتطبيق Next.js/TypeScript مع طبقة Prisma، ومحوّل Gemini، ومحرك توليد صور عبر Sharp وSVG، وموصلات نشر للمنصات الرسمية. يذكر README PostgreSQL مع مسار fallback محلي.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='mghal-content-os';
UPDATE projects SET name_ar='Manar Schedule System', short_description_ar='نظام إدارة الجداول الأكاديمية المخصص لكلية الجامعة اليمنية، ويُعرض كسجل مستقل عن Al-Manar Schedule System المخصص لكلية المنار الجامعية.', description_ar='إدارة الجداول والتغييرات الأكاديمية والطلاب والمحاضرين عبر قنوات منفصلة تؤدي إلى صعوبة نشر التحديثات ومتابعتها.\n\nتوفير بوابات مترابطة للطلاب والإدارة مع محرك جداول وإدارة صلاحيات وإشعارات وسجلات تشغيل.\n\nطلاب ومحاضرو وإداريو كلية الجامعة اليمنية.\n\nتنظيم الجدول الأكاديمي وتعديله مركزياً مع فصل واجهات الأدوار ودعم التنبيهات.\n\nواجهة React/Vite تتصل ببوابة خلفية Express على Node.js. يستخدم المشروع Prisma للوصول إلى PostgreSQL، مع middleware للمصادقة وRBAC وجدولة المهام.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='manar-schedule-system';
UPDATE projects SET name_ar='CipherSphere', short_description_ar='تطبيق سطح مكتب تعليمي للتشفير التطبيقي، يعرض خطوات الخوارزميات والتحويلات الرياضية بصرياً ضمن واجهة PyQt6.', description_ar='يصعب على المتعلم تتبع التحويلات الداخلية لخوارزميات التشفير وفهم أثر كل خطوة عند الاكتفاء بإدخال النص وعرض الناتج.\n\nتوفير مختبر تفاعلي يعرض خطوات التشفير والتحليل بصورة مرئية لأغراض التعلم والتجربة.\n\nطلاب التشفير وأمن المعلومات والمتعلمون الذين يحتاجون إلى رؤية خطوات الخوارزميات.\n\nتحويل الخوارزميات إلى خطوات قابلة للملاحظة مع واجهة رسومية ومحركات منفصلة للخوارزميات.\n\nواجهة PyQt6 رئيسية تتصل بموزع/متحكم للخوارزميات، ثم وحدات Python مستقلة للتشفير الكلاسيكي والمتماثل ونظرية الأعداد والتجزئة والترميز.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='ciphersphere';
UPDATE projects SET name_ar='FocusFlow', short_description_ar='سجل مشروع لتطبيق إنتاجية يركز على المهام وجلسات Pomodoro والعادات والتحليلات اليومية، وفق وصف README.', description_ar='الحاجة إلى مساحة موحدة لمتابعة المهام والتركيز والعادات اليومية.\n\nتصميم تجربة إنتاجية موجهة للجوال تجمع إدارة المهام وجلسات التركيز والعادات.\n\nالأفراد والطلاب الذين يريدون تنظيم وقتهم وعاداتهم.\n\nجمع أدوات الإنتاجية اليومية في تجربة واحدة، وفق وصف المشروع المنشور.\n\nلم يمكن استنتاج معمارية فعلية؛ المستودع العام صغير جداً ويحتوي README فقط ولا يتضمن ملفات مصدر Flutter أو ملفات بناء أو لقطات شاشة.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='focusflow';
UPDATE projects SET name_ar='M.GH.AL — الموقع الرسمي', short_description_ar='موقع شخصي مهني ثنائي اللغة يعرض هوية M.GH.AL والملف المهني والشهادات ومحفظة المشاريع، ببنية ثابتة قابلة للفهرسة.', description_ar='الحاجة إلى مرجع رقمي موحد يعرض الهوية المهنية والأعمال البرمجية بمعلومات قابلة للتحقق بدلاً من تشتتها عبر المنصات.\n\nتقديم موقع عربي وإنجليزي سريع ومتجاوب، مع صفحات مستقلة للمشاريع وبيانات منظمة وتهيئة لمحركات البحث.\n\nالجهات المهنية وفرق التوظيف والعملاء والمطورون والمهتمون بأعمال M.GH.AL.\n\nجمع الهوية والسيرة والمهارات والشهادات والمشاريع في مرجع رسمي واحد مع دعم RTL وLTR.\n\nموقع ثابت يعتمد صفحات HTML وأصول CSS/JavaScript وسجل JSON للمشاريع. ينفذ Node.js مرحلة بناء تولّد صفحات المشاريع وتنسخ مخرجات النشر إلى public، مع تجميع ملفات TypeScript الخاصة بسكربتات المتصفح.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='mghal-official-website';
UPDATE projects SET name_ar='Al-Manar Schedule System', short_description_ar='نظام إدارة الجداول الأكاديمية المخصص لكلية المنار الجامعية، ويُعرض كسجل مستقل عن مشروع Manar Schedule System المخصص لكلية الجامعة اليمنية.', description_ar='إدارة الجداول والتغييرات الأكاديمية والطلاب والمحاضرين عبر قنوات منفصلة تؤدي إلى صعوبة نشر التحديثات ومتابعتها.\n\nتوفير بوابات مترابطة للطلاب والإدارة مع محرك جداول وإدارة صلاحيات وإشعارات وسجلات تشغيل.\n\nطلاب ومحاضرو وإداريو كلية المنار الجامعية.\n\nتنظيم الجدول الأكاديمي وتعديله مركزياً مع فصل واجهات الأدوار ودعم التنبيهات.\n\nواجهة React/Vite تتصل ببوابة خلفية Express على Node.js. يستخدم المشروع Prisma للوصول إلى PostgreSQL، مع middleware للمصادقة وRBAC وجدولة المهام.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='almanar-schedule-system';
UPDATE projects SET name_ar='نظام جداول كلية المنار الجامعية', short_description_ar='نظام لإدارة الجداول الأكاديمية المخصص لكلية المنار الجامعية، مستقل عن مشروع نظام جداول كلية الجامعة اليمنية.', description_ar='تنظيم الجداول والتغييرات الأكاديمية والطلاب والمحاضرين عبر قنوات منفصلة يجعل نشر التحديثات ومتابعتها أكثر صعوبة.\n\nتوفير بوابات مترابطة للطلاب والإدارة مع محرك للجداول وإدارة الصلاحيات والإشعارات والسجلات التشغيلية.\n\nالطلاب والمحاضرون والإداريون في كلية المنار الجامعية.\n\nمركزة الجدولة الأكاديمية والتعديلات مع فصل واجهات الأدوار ومسارات الإشعارات.\n\nواجهة React/Vite تتصل بخلفية Express على Node.js، ويستخدم المشروع Prisma للوصول إلى PostgreSQL مع المصادقة وRBAC والمهام المجدولة.' WHERE slug='almanar-schedule-system';
